System.register([],function(e,t){"use strict";return{execute:function(){e("slide",{render:function(){var e=document.createElement("div");return e.innerHTML='\n      <div style="max-width:800px;margin:0 auto;padding:40px 24px;font-family:sans-serif;" data-edit-path="div.0">\n        <h2 style="font-size:1.8rem;color:#7B2FBE;margin:0 0 8px;" data-edit-path="div.0/h2.0">Python: Sending the Row to Your Sheet</h2>\n        <p style="color:#555;margin:0 0 20px;" data-edit-path="div.0/p.0">After the graphic is generated, this fires automatically and writes the row to your content calendar.</p>\n        <div style="background:#0D0D0D;border-radius:12px;padding:24px;overflow-x:auto;" data-edit-path="div.0/div.0">\n          <pre style="color:#00D4AA;font-family:monospace;font-size:0.82rem;line-height:1.8;margin:0;" data-edit-path="div.0/div.0/pre.0">import urllib.request, urllib.error, json, ssl\n\ndef post_to_sheet(webhook_url, payload):\n    ctx = ssl.create_default_context()\n    ctx.check_hostname = False\n    ctx.verify_mode = ssl.CERT_NONE\n\n    data = json.dumps(payload).encode(\'utf-8\')\n    req = urllib.request.Request(\n        webhook_url, data=data,\n        headers={\'Content-Type\': \'application/json\'},\n        method=\'POST\'\n    )\n    try:\n        with urllib.request.urlopen(req, context=ctx) as r:\n            return json.loads(r.read())\n    except urllib.error.HTTPError as e:\n        if e.code in (301, 302, 307, 308):\n            # Step 2: GET the redirect URL\n            redirect = e.headers.get(\'Location\')\n            with urllib.request.urlopen(redirect, context=ctx) as r2:\n                return json.loads(r2.read())\n        raise</pre>\n        </div>\n        <div style="margin-top:16px;background:#e8f8f4;border-radius:8px;padding:14px 18px;color:#00907a;" data-edit-path="div.0/div.1">\n          <strong data-edit-path="div.0/div.1/strong.0">The two-step redirect is required.</strong> Google Apps Script always redirects — skip it and your POST silently fails every time.\n        </div>\n      </div>',e}})}}});
